from collections import defaultdict

def longestKSubstr(S: str, K: int) -> int:
    if K == 0 or not S:
        return -1

    char_map = defaultdict(int)
    left = 0
    max_length = -1

    for right in range(len(S)):
        char_map[S[right]] += 1

        while len(char_map) > K:
            char_map[S[left]] -= 1
            if char_map[S[left]] == 0:
                del char_map[S[left]]
            left += 1

        if len(char_map) == K:
            max_length = max(max_length, right - left + 1)

    return max_length
